// === Tab: mySketch ===
/**
 * Leaves
 * For the #WCCChallenge << Botanical >> (join the discord! https://discord.gg/S8c7qcjw2b)
 *
 * Tried to generate leaves on this sketch without using a fractal function, and using easing functions
 * combined to determine the shape. Rampensau for generating some color palettes, and some light circle
 * packing to determine the position of the leaves
 */

let cw, ch
let nLeaves
let leafConfigs = []
let leafPoints = []
let maxFrames = 480
let startFrame = 0
let circlePositions
let easeInCirc = t => 1 - sqrt(1 - t * t)
let easeInExpo = t => t == 0 ? 0 : pow(2, 10 * (t - 1))
let easeInBack = t => t * t * ((1.70158 + 1) * t - 1.70158)
let easeInQuad = t => t * t
let easeOutQuint = t => 1 + (--t) * t * t * t * t
let easeOutSine = t => sin(t * PI / 2)
let easeOutCubic = t => 1 + (--t) * t * t

let easeInFunctions = [
  easeInCirc, easeInExpo, easeInBack, easeInQuad
]
let easeOutFunctions = [
  easeOutQuint, easeOutSine, easeOutCubic
]

function setup () {
  cw = windowWidth
  ch = windowHeight
  createCanvas(cw, ch)
  background(255)
  colorMode(HSL, 360, 1, 1, 1)
  noFill()
  initializeConfig()
}

let initializeConfig = () => {
  startFrame = frameCount
  circlePositions = getCirclePos()
  nLeaves = circlePositions.length
  for (let i = 0; i < nLeaves; i++) {
    // Pick random combinations of out, in, out functions
    let fn1 = random(easeOutFunctions)
    let fn2 = random(easeInFunctions)
    let fn3 = random(easeOutFunctions)
    let fn4 = random(easeInFunctions)

    let len = circlePositions[i].d * random(1.2, 1.5) // Inexact packing
    let rotation = noise(circlePositions[i].x * 0.01, circlePositions[i].y * 0.05) * TAU // Use flow field
    let startPos = [
      circlePositions[i].x,
      circlePositions[i].y + random(len / 4)
    ]

    let ramp = rampensau.generateColorRamp({
      total: 4,
      hStart: floor(random(360)),
      hCycles: random(0.3, 0.6),
      hEasing: random(easeInFunctions),
      sRange: [random(0.4, 0.7), random(0.2, 0.4)],
      lRange: [random(0.4, 0.6), random(0.2, 0.8)],
      lEasing: random(easeInFunctions),
    })
    let palette = ramp.map((c) => color(...c).toString('#rrggbb'))
    leafConfigs.push({
      size: len,
      fn1, fn2, fn3, fn4,
      startAngle: -PI/2 + random(-PI/16, PI/16),
      curveFactor: random(0.5, 1),
      initialWobble: random(1000),
      bendSeed: random(10),
      jitter: random(5, 20),
      startPos,
      rotation,
      palette,
      points: [],
			maxNoise: len/random(10,15),
			minNoise: len/random(15,20)
    })
    leafPoints.push([])
  }
  bgColor = color(random(360), random(0.1, 0.3), random(0.9, 1)).toString('#rrggbb')
  background(bgColor)
  stroke('#00000080')
  for (let c of circlePositions) {
    circle(c.x, c.y, c.d)
  }
}

function draw () {
  if (frameCount > startFrame + maxFrames) {
    background(bgColor)
    for (let i = 0; i < leafPoints.length; i++) {
      let leaf = leafPoints[i]
      let leafConfig = leafConfigs[i]
      let len = leafConfig.size
      push()
      translate(...leafConfig.startPos)
      rotate(leafConfig.rotation)

      strokeWeight(3)
      stroke(leafConfig.palette[0])
      for (let j = 0; j < leaf.length; j++) {
        line(...leaf[j][0], ...leaf[j][1])
        line(...leaf[j][1], ...leaf[j][2])
      }

      let sp = random(0.05, 0.1)
      stroke(leafConfig.palette[1] + '80')
      for (let j = 0; j < leaf.length; j++) {
        let s = sin(j * sp)
        s = map(s, -1, 1, 0.2, 0.8)
        s = s * map(wobbly(s, 100), 0, 1, 0.8, 1.2)
        s = s + map(noise(j * 0.1), 0, 1, -0.2, 0.2)
        line(
          ...leaf[j][1],
          ...lerpLine(leaf[j][1], leaf[j][2], s)
        )
        line(
          ...leaf[j][1],
          ...lerpLine(leaf[j][1], leaf[j][0], s)
        )
      }

      let sp2 = random(0.01, 0.3)
      stroke(leafConfig.palette[2] + '80')
      for (let j = 0; j < leaf.length; j++) {
        let s = sin(j * sp2)
        s = map(s, -1, 1, 0.2, 0.8)
        s = s * map(wobbly(s, 100), 0, 1, 0.8, 1.2)
        s = s + map(noise(j * 0.1), 0, 1, -0.2, 0.2)
        line(
          ...leaf[j][1],
          ...lerpLine(leaf[j][1], leaf[j][2], s)
        )
        line(
          ...leaf[j][1],
          ...lerpLine(leaf[j][1], leaf[j][0], s)
        )
      }

      stroke(leafConfig.palette[3] + '40')
      for (let j = 0; j < leaf.length; j++) {
        if (random() < 0.1) {
          let target = random() < 0.5 ? leaf[j][0] : leaf[j][2]
          strokeWeight(random(0.5, 2))
          drawWobblyLine(
            leaf[j][1],
            lerpLine(leaf[j][1], target, random(0.3, 0.6)),
            5,
            len/100
          )
        }
      }
      pop()
    }
    noLoop()
    return
  }
  let p = (frameCount - startFrame) / maxFrames
  for (let i = 0; i < nLeaves; i++) {
    let leafLength = leafConfigs[i].size
    let h = leafLength
    let minLen = 0
    let maxLen = h / 2
    let leafConfig = leafConfigs[i]
    push()
    let leafP = leafPoints[i]
    translate(...leafConfig.startPos)
    rotate(leafConfig.rotation)
    strokeWeight(5)
    getLeafPoints(p, leafLength, minLen, maxLen, leafConfig, leafP)
    pop()
  }
}

// On click regenerate
