/*
  The magic happens here. Now I don't even know what's going on, but the gist is:
  traverse over the "stem" of the leaf, and using easing functions, calculate the rotation
  and length of the leaf (this can be seen on the initial animation phase as it draws the lines)
  The randomness of the leaves comes from the easing functions to use, and some wobble to the stem itself
*/
let getLeafPoints = (p, leafLength, minLen, maxLen, leafConfig, leafPoints) => {
  let {fn1, fn2, fn3, fn4, startAngle, curveFactor, initialWobble, bendSeed, maxNoise, minNoise} = leafConfig
  let nf = 0.08 // Pass as parameter later
  stroke(leafConfig.palette[0])
  let angle = map(fn1(p), 0, 1, startAngle, PI/2)
  let startPos = map(fn4(p), 0, 1, 0, leafLength / 2)
  let x = map(noise(bendSeed + p * leafConfig.jitter), 0, 1, -maxLen/10, maxLen/10)
  let f = mul(fn2, inv(fn3))
  f = mul(fn3, inv(easeInCirc))
  let len = map(f(p), 0, 1, minLen, maxLen)
  let s = sin(PI * p * curveFactor)
  len = len * s
  let nLen = len + map(noise(p * nf), 0, 1, minNoise, maxNoise)
  let wobbliness = wobbly(p, initialWobble + frameCount * nf) * (maxNoise - minNoise) / 10
  nLen = nLen + wobbliness
  let middle = [x, startPos]
  let left = [nLen * cos(angle) + x, startPos + nLen * sin(angle)]
  let right = [-nLen * cos(angle) + x, startPos + nLen * sin(angle)]
  leafPoints.push([left, middle, right])
  // Draw the leaf while collecting the points
  line(...middle, ...left)
  line(...middle, ...right)
  leafConfig.points.push([left, middle, right])
  return leafPoints
}

// Pseudo circle packing, tries to fill in the space with a limited number of tries
let getCirclePos = () => {
  let circles = []
  let minDimension = max(width, height)
  let maxRadius = minDimension / 6
  let minRadius = minDimension / 40

  let _wG_1 = 0; while ((maxRadius >= minRadius) && ++_wG_1 < 20000) {
    let newCircle = createCircle(maxRadius, circles)
    if (newCircle !== null) {
      circles.push(newCircle)
    }
    maxRadius *= 0.98
  }
  return circles
}

let createCircle = (radius, circles, overlapMargin = 0.6) => {
  let safe = false
  let x, y
  for (let tries = 0; tries < 5000; tries++) { // Tries to place a circle without overlapping
    x = random(radius * overlapMargin, cw - radius * overlapMargin)
    y = random(radius * overlapMargin, ch - radius * overlapMargin)
    safe = true
    for (let other of circles) {
      let d = dist(x, y, other.x, other.y)
      if (d < (radius + other.radius) * overlapMargin) {
        safe = false
        break
      }
    }
    if (safe) {
      return { x: x, y: y, radius: radius, d: radius * 2 }
    }
  }
  return null
}

// --- Utils ---

// I like functions
let inv = (fn) => { return t => 1 - fn(1 - t) }
let mul = (fn1, fn2) => { return t => fn1(t) * fn2(t) }

let lerpLine = (p0, p1, n) => {
  return [
    lerp(p0[0], p1[0], n),
    lerp(p0[1], p1[1], n)
  ]
}

let wobbly = (x, t) => {
  return sin(1.2*x - 1*t + 1 + 2*sin(2*x + 1.3*t + 5)**3)
}

let wobblyLine = (p1, p2, segmentLength = 10, wobbleRange = 5) => {
  let [x1, y1] = p1
  let [x2, y2] = p2
  let points = [];
  let dx = x2 - x1
  let dy = y2 - y1
  let lineLength = dist(x1, y1, x2, y2)
  let numSegments = lineLength / segmentLength
  let dirX = dx / lineLength
  let dirY = dy / lineLength
  let perpX = -dirY
  let perpY = dirX

  for (let i = 0; i <= numSegments; i++) {
    let segmentX = x1 + dirX * segmentLength * i
    let segmentY = y1 + dirY * segmentLength * i
    let wobbleOffset = map(noise(i * 0.5), 0, 1, -wobbleRange, wobbleRange) // Use noise to create a smooth wobble
    let wobbleX = segmentX + perpX * wobbleOffset
    let wobbleY = segmentY + perpY * wobbleOffset

    points.push([wobbleX, wobbleY])
  }

  return points
}

let drawWobblyLine = (p1, p2, segmentLength = 10, wobbleRange = 5) => {
  let points = wobblyLine(p1, p2, segmentLength, wobbleRange)
  beginShape()
  for (let p of points) {
    vertex(...p)
  }
  endShape()
}

